import {mountBasinEditor} from './basin-editor.js?v=84';
import {startTitleIntro} from './title-intro.js?v=72';
import {audioMixMarkup,bindAudioMix} from './audio-mix.js?v=keys61fix';
import {loadReplay} from './replay-store.js?v=85';
import {MuseumViewer} from './museum.js?v=85';
export const MAIN_MENU=[
 ['drive','運転乗務','運転乗務は、電車の運転をするゲームです。乗務完了後には、自分の運転をリプレイメニューから見ることもできます。'],
 ['replay','リプレイ','リプレイは、過去に運転した乗務のリプレイを見ることができます。'],
 ['museum','ミュージアム','ミュージアムでは、車両とオブジェクトの3Dモデルを見ることができます。'],
 ['options','オプション','オプションでは、音量、画質、描画距離、揺れの大きさを変更することができます。'],
 ['title','タイトルへ','タイトルへ戻ります。']
];
export function mountGameShell({stage,settings,mix,onSettings,onDrive,onReplay,onSound,onActive,onTitleStart,onPage}){
 const root=document.createElement('section');root.id='gameShell';root.dataset.page='title';root.innerHTML='<div class="shell-glow"></div><div id="shellBody"></div>';stage.append(root);
 const body=root.querySelector('#shellBody');let page='title',selected=0,museum=null,optionReturn='main',replayData=null,titleIntro=null;
 function show(next){titleIntro?.cancel();titleIntro=null;museum?.dispose();museum=null;page=next;root.hidden=false;onActive?.(true);root.dataset.page=page;onPage?.(page);render();}
 function hide(){museum?.dispose();museum=null;root.hidden=true;onActive?.(false);}
 function logo(){return '<img class="shell-logo" src="./assets/trackfinity-logo.svg" alt="Trackfinity Railways">';}
 function heading(en,ja){return `<header class="shell-heading"><small>${en}</small><h1>${ja}</h1></header>`;}
 function description(){const strip=body.querySelector('.shell-description'),text=strip?.querySelector('span');if(!text)return;text.textContent=MAIN_MENU[selected][2];text.style.animation='none';requestAnimationFrame(()=>{if(!text.isConnected)return;const overflow=Math.max(0,text.scrollWidth-strip.clientWidth);text.style.setProperty('--scroll-overflow',-overflow+'px');text.style.setProperty('--scroll-duration',Math.max(9,overflow/65+5)+'s');text.style.animation=overflow?'shell-marquee var(--scroll-duration) linear infinite':'none';});}
 function select(i,sound=true){selected=(i+MAIN_MENU.length)%MAIN_MENU.length;body.querySelectorAll('[data-main]').forEach((b,n)=>{b.classList.toggle('selected',n===selected);b.setAttribute('aria-pressed',String(n===selected));});description();if(sound)onSound('cursor');}
 async function activate(id){onSound('confirm');if(id==='drive'){hide();onDrive();}else if(id==='replay'){show('replay');body.querySelector('.replay-info').textContent='保存した乗務を読み込み中…';try{replayData=await loadReplay();if(page!=='replay')return;renderReplay();}catch{if(page==='replay')body.querySelector('.replay-info').textContent='この端末では保存データを読み込めませんでした。';}}else show(id==='options'?'options':id);}
 function back(){onSound('cancel');if(page==='scenery')show('options');else if(page==='main')show('title');else if(page==='options'&&optionReturn==='drive'){hide();onSettings('close');}else show('main');}
 function renderReplay(){body.innerHTML=heading('REPLAY','リプレイ')+'<div class="replay-info"></div><div class="shell-actions"><button data-back>◀ メインメニュー</button><button id="watchReplay">▶ 再生する</button></div>';const info=body.querySelector('.replay-info'),button=body.querySelector('#watchReplay');button.disabled=!replayData?.samples?.length;if(button.disabled)info.textContent='保存された乗務はありません。運転乗務を始めると、この端末に直近の1件が自動保存されます。';else{const a=replayData.samples[0],b=replayData.samples.at(-1);info.textContent=`${replayData.lineName}　${replayData.trainName}\n${replayData.from} → ${replayData.to}\n${new Date(replayData.created).toLocaleString('ja-JP')}　記録 ${Math.floor((b.elapsed-a.elapsed)/60)}分${Math.floor((b.elapsed-a.elapsed)%60)}秒\n${b.finished?'乗務完了':'途中までの乗務'} · ${b.points} points　${b.chain} chain\n保存先：この端末・このブラウザー（直近1件）`;}button.onclick=()=>{onSound('confirm');hide();onReplay(replayData);};body.querySelector('[data-back]').onclick=back;}
 function render(){
  if(page==='title'){body.innerHTML=logo()+'<div class="title-train-band" aria-label="7路線の電車が左から右へ走ります"><div class="title-train-track"></div><img class="title-train" src="./assets/trackfinity-train.svg?v=82" alt="山手線・中央線系統・大阪環状線・東海道線・東北本線・野岩鉄道・東方鉄道線のラインカラー"></div><button class="title-start">PRESS ENTER / TOUCH TO START</button><p class="title-caption">YOUR NEXT JOURNEY STARTS HERE</p>';titleIntro=startTitleIntro({image:body.querySelector('.shell-logo'),button:body.querySelector('button'),onEnter:()=>onTitleStart?.(),onStart:()=>show('main')});body.onclick=event=>{if(page==='title'&&body.contains(event.target))titleIntro?.enter();};return;}
  if(page==='main'){body.innerHTML=logo()+'<div class="shell-menu"><small>MAIN MENU</small>'+MAIN_MENU.map(([id,name],i)=>`<button data-main="${id}"><i>0${i+1}</i>${name}<b>▶</b></button>`).join('')+'</div><div class="shell-description"><span></span></div><div class="shell-key-guide">↑↓ 選択　Enter 決定　Esc タイトルへ</div>';body.querySelectorAll('[data-main]').forEach((b,i)=>{b.onpointerenter=()=>{if(selected!==i)select(i);};b.onfocus=()=>{if(selected!==i)select(i);};b.onclick=()=>activate(b.dataset.main);});select(selected,false);return;}
  if(page==='replay'){renderReplay();return;}
  if(page==='scenery'){mountBasinEditor(body,{onChange:()=>onSettings('scenery'),onBack:back,onSound});return;}
  if(page==='options'){body.innerHTML=heading('OPTION','オプション')+'<div class="shell-options">'+audioMixMarkup(mix)+'<label>描画距離 <output id="distanceValue"></output><input id="drawDistance" aria-label="描画距離" type="range" min="500" max="2000" step="250"></label><label>揺れの大きさ <output id="shakeValue"></output><input id="shellShake" aria-label="揺れの大きさ" type="range" min="0" max="100" step="10"></label><div class="quality-buttons"><span>描画品質</span><button data-quality="standard">通常表示</button><button data-quality="light">簡易表示</button><small>通常：影・動く雲あり　／　簡易：影・雲なし</small></div></div><div class="shell-actions"><button data-back>◀ 戻る</button><button class="basin-profile-open" id="openBasinProfile">沿線景観グラフ · 全路線 ▶</button></div>';body.querySelector('#openBasinProfile').onclick=()=>{onSound('confirm');show('scenery');};bindAudioMix(body,mix,()=>onSettings('mix'));const distance=body.querySelector('#drawDistance'),shake=body.querySelector('#shellShake');distance.value=settings.drawDistance??1500;shake.value=settings.shake*100;const update=()=>{body.querySelector('#distanceValue').textContent=distance.value+' m';body.querySelector('#shakeValue').textContent=shake.value+'%';body.querySelectorAll('[data-quality]').forEach(b=>{b.classList.toggle('selected',b.dataset.quality===settings.quality);b.setAttribute('aria-pressed',String(b.dataset.quality===settings.quality));});};distance.oninput=()=>{settings.drawDistance=Number(distance.value);update();onSettings('settings');};shake.oninput=()=>{settings.shake=Number(shake.value)/100;update();onSettings('settings');};body.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{onSound('cursor');settings.quality=b.dataset.quality;update();onSettings('settings');});update();body.querySelector('[data-back]').onclick=back;return;}
  if(page==='museum'){body.innerHTML=heading('MUSEUM','ミュージアム')+'<div id="museumCanvas"></div><div class="museum-selector">'+[['e235','E235系'],['e233','E233系'],['323','323系'],['221','221系'],['211','211系'],['701','701系'],['223','223系2000番台'],['223-0','223系0番台'],['383','383系'],['681','681系'],['e353','E353系'],['6050','東武6050系'],['track','レール'],['platform','ホーム'],['bridge','橋梁'],['tunnel','トンネル']].map(([id,name])=>`<button data-model="${id}">${name}</button>`).join('')+'</div><p id="museumStatus">3Dモデルを読み込み中…</p><p class="museum-help">ドラッグで回転・ホイール／ピンチでズーム　←→ 車両・構造物　↑↓ 視点　＋− ズーム</p><div class="shell-actions"><button data-back>◀ メインメニュー</button></div>';museum=new MuseumViewer(body.querySelector('#museumCanvas'),body.querySelector('#museumStatus'));const choose=id=>{onSound('cursor');body.querySelectorAll('[data-model]').forEach(b=>b.classList.toggle('selected',b.dataset.model===id));body.querySelector('[data-model="'+id+'"]')?.scrollIntoView({block:'nearest',inline:'nearest'});museum.show(id);};body.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>choose(b.dataset.model));body.querySelector('[data-model]').classList.add('selected');museum.show('e235');body.querySelector('[data-back]').onclick=back;}
 }
 document.addEventListener('keydown',e=>{
  if(root.hidden)return;if(e.altKey||e.ctrlKey||e.metaKey)return;
  const codes=['Enter','Escape','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Equal','Minus','NumpadAdd','NumpadSubtract'];if(!codes.includes(e.code))return;e.stopImmediatePropagation();
  if(page==='scenery'&&e.target.matches('select')&&e.code!=='Escape')return;
  if(['options','scenery'].includes(page)&&e.target.matches('input[type=range]')&&['ArrowLeft','ArrowRight'].includes(e.code))return;e.preventDefault();
  if(e.code==='Escape'){if(page!=='title')back();return;}
  if(page==='title'){if(e.code==='Enter'&&!e.repeat)titleIntro?.enter();return;}
  if(page==='main'){if(['ArrowUp','ArrowDown'].includes(e.code))select(selected+(e.code==='ArrowDown'?1:-1));else if(e.code==='Enter'&&!e.repeat)activate(MAIN_MENU[selected][0]);return;}
  if(page==='scenery'&&e.target.closest('[data-station]')&&e.code==='Enter'){e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return;}
  if(page==='museum'&&e.code!=='Enter'){if(['ArrowLeft','ArrowRight'].includes(e.code)){const items=[...body.querySelectorAll('[data-model]')],i=items.findIndex(b=>b.classList.contains('selected'));items[(i+(e.code==='ArrowRight'?1:-1)+items.length)%items.length].click();}else museum?.key(e.code);return;}
  const buttons=[...body.querySelectorAll('button:not(:disabled),input')],i=buttons.indexOf(document.activeElement);if(e.code==='Enter'){if(document.activeElement?.tagName==='BUTTON')document.activeElement.click();else buttons[(i+1)%buttons.length]?.focus();}else buttons[(i+(e.code==='ArrowUp'?-1:1)+buttons.length)%buttons.length]?.focus();
 },true);
 onPage?.(page);render();onActive?.(true);
 return {get active(){return !root.hidden;},showMain(){optionReturn='main';show('main');},showTitle(){show('title');},showOptions(from='main'){optionReturn=from;show('options');},hide};
}
